static bool pending=false,decorated=true;static unsigned layerCount=2;static bool invalid=false;
static bool ends(const std::string& s,const std::string& suffix){return s.size()>=suffix.size()&&s.compare(s.size()-suffix.size(),suffix.size(),suffix)==0;}
static bool itemPath(const std::string& p){return p.find("inventory.held.")==0||p.find("inventory.offhand.")==0||p.find("inventory.items.0.")==0;}
extern "C" TcpeJavaSession* tcpe_java_connect(const char*,size_t,const char*,size_t,bool){return reinterpret_cast<TcpeJavaSession*>(1);}
extern "C" void tcpe_java_close(TcpeJavaSession*){}
extern "C" int tcpe_java_poll(TcpeJavaSession*,TcpeJavaEvent* e){if(!pending)return 0;pending=false;*e=TcpeJavaEvent{};e->kind=TCPE_JAVA_INVENTORY;return 1;}
extern "C" bool tcpe_java_text(const TcpeJavaSession*,const char* p,size_t n,TcpeJavaText* result){const std::string key(p,n);static std::string value;if(key=="inventory.menu_kind")value="player";else if(itemPath(key)&&ends(key,".resource_id"))value="minecraft:shield";else if(itemPath(key)&&ends(key,".kind"))value="Shield";else if(itemPath(key)&&ends(key,".asset_id"))value=invalid?"minecraft:../bad":key.find(".layers.0.")!=std::string::npos?"minecraft:stripe_top":"minecraft:cross";else return false;result->data=reinterpret_cast<const uint8_t*>(value.data());result->len=value.size();return true;}
extern "C" bool tcpe_java_array_size(const TcpeJavaSession*,const char* p,size_t n,size_t* out){const std::string key(p,n);if(key=="inventory.items"){*out=1;return true;}if(itemPath(key)&&ends(key,".shield.layers")){*out=decorated?layerCount:0;return true;}return false;}
extern "C" bool tcpe_java_boolean(const TcpeJavaSession*,const char* p,size_t n,bool* out){const std::string key(p,n);if(itemPath(key)&&ends(key,".shield.patterned")){*out=decorated;return true;}if(itemPath(key)&&ends(key,".shield.complete")){*out=true;return true;}return false;}
extern "C" bool tcpe_java_number(const TcpeJavaSession*,const char* p,size_t n,double* out){const std::string key(p,n);if(key=="inventory.window_id"){*out=0;return true;}if(key=="inventory.menu_generation"){*out=9;return true;}if(itemPath(key)&&ends(key,".count")){*out=1;return true;}if(itemPath(key)&&ends(key,".shield.base_color")&&decorated){*out=11;return true;}if(itemPath(key)&&ends(key,".color")){*out=key.find(".layers.0.")!=std::string::npos?14:4;return true;}return false;}
